payment.html.preflight_fragment:
/*
   Fast preflight for Excel Preview: reject empty/header-only sheets and
   missing required column mappings BEFORE reading the entire payments
   history. For any potentially valid data, keep the original full-history
   comparison unchanged (including cross-month IPC warnings).
   This helper makes no Firebase request and never changes imported rows.
*/
function importPreviewNeedsHistoryScan(){
    const matrix = parseExcelClipboard(excelPasteArea.value);
    if(!matrix.length) return false;

    const required = ["contractNo", "ipcNo", "amount"];
    if(excelImportMode === "no-header"){
        const map = buildManualHeaderMap(matrix[0].length);
        return required.every(key => map[key] !== undefined);
    }
    if(looksLikeHeaderRow(matrix[0])){
        if(matrix.length === 1) return false;
        const map = buildImportHeaderMap(matrix[0]);
        return required.every(key => map[key] !== undefined);
    }
    return true;
}

